import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";
const root = process.argv[1];
const directory = join(root, "skill-artifacts");
const report = JSON.parse(readFileSync(join(directory, "report.json"), "utf8"));
const artifacts = [...report.sharedArtifacts, ...report.provenance.flatMap((item) => item.artifacts)];
const mismatches = artifacts.filter((artifact) => createHash("sha256").update(readFileSync(join(directory, artifact.path))).digest("hex") !== artifact.sha256);
if (report.attempts.length !== 13 || report.assessments.length !== 13 || artifacts.length !== 66 || mismatches.length !== 0) process.exit(1);
console.log(JSON.stringify({ mode: report.adapter.mode, attempts: report.attempts.length, assessments: report.assessments.length, artifacts: artifacts.length, passed: report.assessments.filter((item) => item.status === "passed").length, digestMismatches: mismatches.length }));
